import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String first = sc.nextLine();
        String second = sc.nextLine();

        System.out.println(first + " 有 " + first.length() + " 个字喵");
        System.out.println(second + " 有 " + second.length() + " 个字喵");
        System.out.println("最长的有 " + Math.max(first.length(), second.length()) + " 个字喵");
    }
}
